<template>
  <div :class="{ field: withMargin, 'is-inline': isInline }">
    <label class="label" :for="fieldId" v-if="label.length > 0">
      {{ label }}
    </label>
    <p class="control" :class="{ 'is-inline': isInline }">
      <span class="select" :class="{ 'is-top': isTop }">
        <select
          :id="fieldId"
          class="combobox select-input"
          :class="{
            thin,
            error,
            touched
          }"
          :style="{
            width: width ? `${width}px` : undefined
          }"
          ref="selectRef"
          :disabled="disabled"
          :required="required && !hasSelectedOption"
          @keyup.enter="emitEnter()"
          @change="updateValue"
          @blur="touched = true"
        >
          <option v-if="!hasSelectedOption" value="" disabled selected></option>
          <template
            v-for="(option, index) in options"
            :key="`${index}-${option.label}-${option.value}`"
          >
            <option
              :value="option.label || option.value"
              :selected="modelValue === option.value || null"
              :disabled="option.disabled"
            >
              {{ getOptionLabel(option) }}
            </option>
            <hr v-if="option.separator" />
          </template>
        </select>
      </span>
    </p>
  </div>
</template>

<script setup>
// Imports
// --------------------------------------------------------------------------
import { computed, ref, useId } from 'vue'
import { useI18n } from 'vue-i18n'

const { t } = useI18n()

const fieldId = useId()

// Props / Emits
// --------------------------------------------------------------------------
const props = defineProps({
  label: {
    default: '',
    type: String
  },
  modelValue: {
    default: '',
    type: [Object, String, Boolean, Number]
  },
  options: {
    default: () => [],
    type: Array
  },
  localeKeyPrefix: {
    default: '',
    type: String
  },
  isTop: {
    default: false,
    type: Boolean
  },
  disabled: {
    default: false,
    type: Boolean
  },
  error: {
    default: false,
    type: Boolean
  },
  thin: {
    default: false,
    type: Boolean
  },
  width: {
    type: Number
  },
  withMargin: {
    default: true,
    type: Boolean
  },
  isInline: {
    default: false,
    type: Boolean
  },
  required: {
    default: false,
    type: Boolean
  }
})

const emit = defineEmits(['enter', 'update:model-value'])

// State
// --------------------------------------------------------------------------
const selectRef = ref(null)
const touched = ref(false)

// Computed
// --------------------------------------------------------------------------
const hasSelectedOption = computed(() =>
  props.options.some(option => option.value === props.modelValue)
)

const isValid = computed(() => !props.required || hasSelectedOption.value)

// Functions
// --------------------------------------------------------------------------
const getSelectedValue = () => {
  const selected = selectRef.value.value
  return props.options.reduce(
    (value, option) => (option.label === selected ? option.value : value),
    selected
  )
}

const updateValue = () => emit('update:model-value', getSelectedValue())

const emitEnter = () => emit('enter', getSelectedValue())

const getOptionLabel = option => {
  if (props.localeKeyPrefix && option.label) {
    return t(props.localeKeyPrefix + option.label.toLowerCase())
  }
  return option.label
}

const focus = () => {
  touched.value = true
  selectRef.value?.focus()
}

defineExpose({ isValid, focus })
</script>

<style lang="scss" scoped>
.dark select:disabled {
  background: $dark-grey;
  border-color: $dark-grey-strong;
}

.is-top select {
  font-size: 1.2em;
  border: 0;
  border-bottom: 1px solid $light-grey;
  border-radius: 0;
  height: 38px;
}

.is-top select:focus {
  border-color: $green;
  outline: 0;
}

.select-input {
  height: 3em;

  &.thin {
    height: 2.1em;
  }

  &.touched:invalid {
    border-color: $red;
  }
}

.select {
  height: auto;
}
.select::after {
  border: 1px solid $green;
  border-right: 0;
  border-top: 0;
  margin-top: -4px;
}

.select.is-top::after {
  border: 2px solid $green;
  border-right: 0;
  border-top: 0;
  margin-top: -4px;
}

.error {
  border-color: $red;
}
</style>
